printf 'name: cycle-test
stages:
  - {id: a, type: command, command: "echo a", depends_on: [b]}
  - {id: b, type: command, command: "echo b", depends_on: [a]}
' > /tmp/cycle-test.yml && python3 scripts/orchestrate-dispatch.py /tmp/cycle-test.yml 2>&1; echo "rc=$?"

printf 'name: mixed-test
stages:
  - id: fan
    type: parallel
    stages:
      - {id: a, type: agent, agent_type: claude, prompt: x}
      - {id: b, type: agent, agent_type: claude, prompt: y}
      - {id: c, type: command, command: "true"}
' > /tmp/mixed-test.yml && python3 scripts/orchestrate-dispatch.py /tmp/mixed-test.yml 2>&1 | grep -E 'F8.4 UNDER|agent sub-stage' | head -3
